"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7548],{67548:e=>{e.exports=JSON.parse('{"slug":"bessent-khe-lifen-peregovory-tramp-si","locale":"ru","title":"\u0411\u0435\u0441\u0441\u0435\u043d\u0442 \u0438 \u0425\u044d \u041b\u0438\u0444\u044d\u043d \u043f\u0440\u043e\u0432\u0435\u043b\u0438 \u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u044b \u0432 \u041d\u044c\u044e-\u0419\u043e\u0440\u043a\u0435 \u0437\u0430 4 \u0434\u043d\u044f \u0434\u043e \u0432\u0441\u0442\u0440\u0435\u0447\u0438 \u0422\u0440\u0430\u043c\u043f\u0430 \u0438 \u0421\u0438","description":"\u041c\u0438\u043d\u0438\u0441\u0442\u0440 \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432 \u0421\u0428\u0410 \u0421\u043a\u043e\u0442\u0442 \u0411\u0435\u0441\u0441\u0435\u043d\u0442 \u0432 \u0432\u043e\u0441\u043a\u0440\u0435\u0441\u0435\u043d\u044c\u0435 \u0432\u0441\u0442\u0440\u0435\u0442\u0438\u043b\u0441\u044f \u0432 \u041d\u044c\u044e-\u0419\u043e\u0440\u043a\u0435 \u0441 \u0432\u0438\u0446\u0435-\u043f\u0440\u0435\u043c\u044c\u0435\u0440\u043e\u043c \u041a\u041d\u0420 \u0425\u044d \u041b\u0438\u0444\u044d\u043d\u043e\u043c \u043f\u0435\u0440\u0435\u0434 \u0432\u0441\u0442\u0440\u0435\u0447\u0435\u0439 \u0422\u0440\u0430\u043c\u043f\u0430 \u0438 \u0421\u0438 \u0432 \u0447\u0435\u0442\u0432\u0435\u0440\u0433. \u041d\u0430 \u043a\u043e\u043d\u0443 \u043f\u0440\u043e\u0434\u043b\u0435\u043d\u0438\u0435 \u0442\u043e\u0440\u0433\u043e\u0432\u043e\u0433\u043e \u043f\u0435\u0440\u0435\u043c\u0438\u0440\u0438\u044f \u0434\u0432\u0443\u0445 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a, \u0430 \u0434\u043b\u044f \u0420\u043e\u0441\u0441\u0438\u0438 \u044d\u0442\u043e \u0432\u043e\u043f\u0440\u043e\u0441 \u0441\u043f\u0440\u043e\u0441\u0430 \u043d\u0430 \u043d\u0435\u0444\u0442\u044c.","blocks":[{"id":"b001","kind":"paragraph","text":"\u0411\u0435\u0441\u0441\u0435\u043d\u0442 \u043d\u0430\u043f\u0438\u0441\u0430\u043b \u0432 X, \u0447\u0442\u043e \u043e\u043d\u0438 \u0441 \u0425\u044d \u041b\u0438\u0444\u044d\u043d\u043e\u043c \xab\u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u044e\u0442 \u043e\u0431\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u0435 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u043e-\u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0445 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0438 \u0442\u043e\u0440\u0433\u043e\u0432\u044b\u0445 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0439\xbb \u043f\u0435\u0440\u0435\u0434 \xab\u0438\u0441\u0442\u043e\u0440\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0432\u0441\u0442\u0440\u0435\u0447\u0435\u0439\xbb \u0422\u0440\u0430\u043c\u043f\u0430 \u0438 \u0421\u0438 \u0432 \u0412\u0430\u0448\u0438\u043d\u0433\u0442\u043e\u043d\u0435, \u0438 \u043f\u0440\u0438\u043b\u043e\u0436\u0438\u043b \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u044c\u043d\u043e\u0435 \u0444\u043e\u0442\u043e \u043d\u0430 \u0444\u043e\u043d\u0435 \u0444\u043b\u0430\u0433\u043e\u0432. \u0414\u0440\u0443\u0433\u0438\u0445 \u043f\u043e\u0434\u0440\u043e\u0431\u043d\u043e\u0441\u0442\u0435\u0439 \u043e\u043d \u043d\u0435 \u043f\u0440\u0438\u0432\u0451\u043b. \u041f\u043e\u0437\u0436\u0435 \u0411\u0435\u0441\u0441\u0435\u043d\u0442 \u043d\u0430\u0437\u0432\u0430\u043b \u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u044b \u0443\u0441\u043f\u0435\u0448\u043d\u044b\u043c\u0438 \u0438 \u0441\u043a\u0430\u0437\u0430\u043b, \u0447\u0442\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0441\u043e\u0441\u0440\u0435\u0434\u043e\u0442\u043e\u0447\u0438\u043b\u0438\u0441\u044c \u043d\u0430 \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0435 \u0438 \u0438\u0441\u043a\u0443\u0441\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u043c \u0438\u043d\u0442\u0435\u043b\u043b\u0435\u043a\u0442\u0435. \u0421\u0438\u043d\u044c\u0445\u0443\u0430 \u0432\u0441\u0442\u0440\u0435\u0447\u0443 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u043b\u043e. \u0421\u0430\u043c\u0430 \u0432\u0441\u0442\u0440\u0435\u0447\u0430 \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u043e\u0432 \u043f\u0440\u043e\u0439\u0434\u0451\u0442 \u0432 \u0447\u0435\u0442\u0432\u0435\u0440\u0433, 24 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u044f."},{"id":"b002","kind":"paragraph","text":"\u041f\u043e\u0432\u0435\u0441\u0442\u043a\u0430 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u0430 \u0438\u0437 \u043f\u0440\u0435\u0432\u044c\u044e: \u0442\u0430\u0440\u0438\u0444\u044b, \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0446\u0438\u044f \u0432 \u0418\u0418, \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043d\u0430\u0434 \u043f\u043e\u043b\u0443\u043f\u0440\u043e\u0432\u043e\u0434\u043d\u0438\u043a\u0430\u043c\u0438, \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0445 \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043c\u043e\u0431\u0438\u043b\u0435\u0439 \u0432 \u0421\u0428\u0410, \u0430 \u0444\u043e\u043d\u043e\u043c \u0422\u0430\u0439\u0432\u0430\u043d\u044c \u0438 \u0418\u0440\u0430\u043d. \u0421 \u043c\u0430\u0439\u0441\u043a\u043e\u0439 \u0432\u0441\u0442\u0440\u0435\u0447\u0438 \u043b\u0438\u0434\u0435\u0440\u043e\u0432 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044f \u0443\u0445\u0443\u0434\u0448\u0438\u043b\u0438\u0441\u044c: \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u0435 \u0447\u0438\u043d\u043e\u0432\u043d\u0438\u043a\u0438 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u043e \u0433\u043e\u0432\u043e\u0440\u044f\u0442, \u0447\u0442\u043e \u041a\u0438\u0442\u0430\u0439 \u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442 \u0443\u0441\u043b\u043e\u0432\u0438\u044f \u0433\u043e\u0434\u043e\u0432\u043e\u0433\u043e \u0442\u043e\u0440\u0433\u043e\u0432\u043e\u0433\u043e \u043f\u0435\u0440\u0435\u043c\u0438\u0440\u0438\u044f. \u041d\u0430\u0434 \u0432\u0441\u0442\u0440\u0435\u0447\u0435\u0439 \u043d\u0430\u0432\u0438\u0441\u0430\u044e\u0442 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0435 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f \u043d\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u043a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u043e\u0432 \u0438 \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0443\u0436\u0435 \u0432\u044b\u0437\u0432\u0430\u043b\u0438 \u043f\u0435\u0440\u0435\u0431\u043e\u0438 \u0443 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u0445 \u0438 \u0434\u0440\u0443\u0433\u0438\u0445 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439."},{"id":"b003","kind":"paragraph","text":"\u0421\u0430\u043c\u043e \xab\u0442\u043e\u0440\u0433\u043e\u0432\u043e\u0435 \u043f\u0435\u0440\u0435\u043c\u0438\u0440\u0438\u0435\xbb \u0443\u0441\u0442\u0440\u043e\u0435\u043d\u043e \u043f\u0440\u043e\u0441\u0442\u043e. \u0413\u043e\u0434 \u043d\u0430\u0437\u0430\u0434 \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u043b\u0438\u0441\u044c \u043d\u0435 \u043f\u043e\u0434\u043d\u0438\u043c\u0430\u0442\u044c \u0434\u0440\u0443\u0433 \u0434\u0440\u0443\u0433\u0443 \u0442\u0430\u0440\u0438\u0444\u044b \u0438 \u043d\u0435 \u0432\u0432\u043e\u0434\u0438\u0442\u044c \u043d\u043e\u0432\u044b\u0435 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f. \u042d\u0442\u043e \u043f\u0430\u0443\u0437\u0430 \u0432 \u0441\u0441\u043e\u0440\u0435 \u0441 \u0434\u0430\u0442\u043e\u0439 \u043e\u043a\u043e\u043d\u0447\u0430\u043d\u0438\u044f: \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u043b\u0438\u0441\u044c \u043d\u0435 \u0440\u0443\u0433\u0430\u0442\u044c\u0441\u044f, \u0430 \u043f\u043e\u0442\u043e\u043c \u0440\u0435\u0448\u0430\u0442\u044c, \u043f\u0440\u043e\u0434\u043b\u0435\u0432\u0430\u0442\u044c \u043f\u0430\u0443\u0437\u0443 \u0438\u043b\u0438 \u043d\u0435\u0442. \u0421\u0440\u043e\u043a \u043f\u043e\u0434\u0445\u043e\u0434\u0438\u0442 \u043a \u043a\u043e\u043d\u0446\u0443, \u0438 \u0432 \u044d\u0442\u043e\u043c \u0433\u043b\u0430\u0432\u043d\u0430\u044f \u0438\u043d\u0442\u0440\u0438\u0433\u0430 \u0447\u0435\u0442\u0432\u0435\u0440\u0433\u0430. \u041d\u0435 \u0432 \u0442\u043e\u043c, \u0447\u0442\u043e \u0442\u0430\u043c \u043f\u043e\u0434\u043f\u0438\u0448\u0443\u0442 \u0447\u0442\u043e-\u0442\u043e \u0431\u043e\u043b\u044c\u0448\u043e\u0435, \u0430 \u0432 \u0442\u043e\u043c, \u0447\u0442\u043e \u043c\u043e\u0433\u0443\u0442 \u043d\u0435 \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u0442\u044c \u043d\u0438\u0447\u0435\u0433\u043e. \u0422\u043e\u0433\u0434\u0430 \u043f\u0435\u0440\u0435\u043c\u0438\u0440\u0438\u0435 \u043f\u0440\u043e\u0441\u0442\u043e \u0437\u0430\u043a\u0430\u043d\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044f, \u0438 \u043e\u0431\u0435 \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0441\u043d\u043e\u0432\u0430 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u044b \u0432 \u0442\u0430\u0440\u0438\u0444\u0430\u0445."},{"id":"b004","kind":"paragraph","text":"\u0420\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u044b \u0432 \u044d\u0442\u043e\u043c \u0442\u043e\u0440\u0433\u0435 \u0440\u0430\u0431\u043e\u0442\u0430\u044e\u0442 \u043a\u0430\u043a \u0440\u044b\u0447\u0430\u0433. \u041e\u043d\u0438 \u043d\u0443\u0436\u043d\u044b \u0434\u043b\u044f \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043d\u0438\u043a\u0438, \u0431\u0430\u0442\u0430\u0440\u0435\u0439 \u0438 \u043e\u0440\u0443\u0436\u0438\u044f, \u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0438\u0437 \u041a\u0438\u0442\u0430\u044f \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d. \u042d\u0442\u043e \u043a\u0430\u043a \u0435\u0441\u043b\u0438 \u0431\u044b \u0443 \u0430\u0432\u0442\u043e\u0437\u0430\u0432\u043e\u0434\u0430 \u0431\u044b\u043b \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u043f\u043e\u0441\u0442\u0430\u0432\u0449\u0438\u043a \u043e\u0434\u043d\u043e\u0439 \u0434\u0435\u0442\u0430\u043b\u0438: \u043e\u043d \u0434\u0438\u043a\u0442\u0443\u0435\u0442 \u0446\u0435\u043d\u0443 \u0438 \u0441\u0440\u043e\u043a\u0438, \u0430 \u0437\u0430\u0432\u043e\u0434 \u043d\u0435 \u043c\u043e\u0436\u0435\u0442 \u0441\u043e\u0431\u0440\u0430\u0442\u044c \u043c\u0430\u0448\u0438\u043d\u0443 \u0431\u0435\u0437 \u043d\u0435\u0451. \u041f\u043e\u044d\u0442\u043e\u043c\u0443 \u043f\u0435\u0440\u0435\u0431\u043e\u0438 \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u0435\u0435 \u0442\u0430\u0440\u0438\u0444\u043e\u0432: \u0441 \u0442\u0430\u0440\u0438\u0444\u043e\u043c \u0434\u0435\u0442\u0430\u043b\u044c \u0434\u043e\u0440\u043e\u0436\u0430\u0435\u0442, \u0431\u0435\u0437 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0435\u0451 \u043d\u0435\u0442 \u0441\u043e\u0432\u0441\u0435\u043c."},{"id":"b005","kind":"paragraph","text":"\u0420\u044b\u043d\u043a\u0438 \u043f\u043e\u043a\u0430 \u0436\u0434\u0443\u0442, \u0430 \u043d\u0435 \u0441\u0442\u0430\u0432\u044f\u0442. \u0424\u044c\u044e\u0447\u0435\u0440\u0441\u044b \u043d\u0430 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u0435 \u0438\u043d\u0434\u0435\u043a\u0441\u044b \u0432 \u043f\u043e\u043d\u0435\u0434\u0435\u043b\u044c\u043d\u0438\u043a \u0447\u0443\u0442\u044c \u043f\u043e\u0434\u0440\u043e\u0441\u043b\u0438, \u0434\u043e\u043b\u043b\u0430\u0440 \u0434\u0435\u0440\u0436\u0430\u043b\u0441\u044f \u0432 \u0443\u0437\u043a\u043e\u043c \u043a\u043e\u0440\u0438\u0434\u043e\u0440\u0435. \u042d\u0442\u043e \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435, \u043a\u043e\u0433\u0434\u0430 \u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u0445\u043e\u0447\u0435\u0442 \u0443\u0433\u0430\u0434\u044b\u0432\u0430\u0442\u044c \u0438\u0441\u0445\u043e\u0434. \u0427\u0435\u043c \u0437\u0430\u043a\u043e\u043d\u0447\u0438\u0442\u0441\u044f \u0447\u0435\u0442\u0432\u0435\u0440\u0433, \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e, \u0438 \u043e\u0431\u0430 \u043b\u0438\u0434\u0435\u0440\u0430 \u0443\u043c\u0435\u044e\u0442 \u0434\u043e \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0435\u0433\u043e \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0442\u044c \u0433\u043e\u0442\u043e\u0432\u043d\u043e\u0441\u0442\u044c \u0438 \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u044c\u0441\u044f, \u0438 \u0445\u043b\u043e\u043f\u043d\u0443\u0442\u044c \u0434\u0432\u0435\u0440\u044c\u044e."},{"id":"b006","kind":"paragraph","text":"\u0414\u043b\u044f \u0420\u043e\u0441\u0441\u0438\u0438 \u043f\u0440\u044f\u043c\u043e\u0433\u043e \u043a\u0430\u043d\u0430\u043b\u0430 \u0437\u0434\u0435\u0441\u044c \u043d\u0435\u0442: \u043d\u0438 \u043e\u0434\u0438\u043d \u043f\u0443\u043d\u043a\u0442 \u043f\u043e\u0432\u0435\u0441\u0442\u043a\u0438 \u043d\u0435 \u043a\u0430\u0441\u0430\u0435\u0442\u0441\u044f \u0440\u043e\u0441\u0441\u0438\u0439\u0441\u043a\u043e\u0433\u043e \u0438\u043c\u043f\u043e\u0440\u0442\u0430 \u0438\u043b\u0438 \u0440\u0443\u0431\u043b\u044f. \u041a\u0430\u043d\u0430\u043b \u0434\u043b\u0438\u043d\u043d\u044b\u0439. \u0415\u0441\u043b\u0438 \u0421\u0428\u0410 \u0438 \u041a\u0438\u0442\u0430\u0439 \u0441\u043d\u043e\u0432\u0430 \u043d\u0430\u0447\u043d\u0443\u0442 \u043f\u043e\u0434\u043d\u0438\u043c\u0430\u0442\u044c \u0442\u0430\u0440\u0438\u0444\u044b, \u043c\u0438\u0440\u043e\u0432\u0430\u044f \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u044f \u0437\u0430\u043c\u0435\u0434\u043b\u044f\u0435\u0442\u0441\u044f, \u0430 \u0441 \u043d\u0435\u0439 \u0441\u043f\u0440\u043e\u0441 \u043d\u0430 \u043d\u0435\u0444\u0442\u044c, \u0430 \u043d\u0435\u0444\u0442\u044c \u044d\u0442\u043e \u0434\u043e\u0445\u043e\u0434\u044b \u0431\u044e\u0434\u0436\u0435\u0442\u0430 \u0438 \u043e\u043f\u043e\u0440\u0430 \u043a\u0443\u0440\u0441\u0430. \u0415\u0441\u043b\u0438 \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u044f\u0442\u0441\u044f, \u0434\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u043d\u0430 \u043d\u0435\u0444\u0442\u044c \u0441 \u044d\u0442\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0443\u0445\u043e\u0434\u0438\u0442. \u041e\u0446\u0435\u043d\u043a\u0438 \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0430 \u043d\u0435\u0442."},{"id":"b007","kind":"paragraph","text":"\u0414\u043b\u044f \u043e\u0431\u044b\u0447\u043d\u043e\u0433\u043e \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u0430 \u044d\u0442\u043e \u043d\u043e\u0432\u043e\u0441\u0442\u044c, \u043f\u043e \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u043d\u0435 \u0441\u0442\u043e\u0438\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c, \u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u043b\u0435\u0434\u0438\u0442\u044c. \u041f\u043e\u043a\u0443\u043f\u0430\u0442\u044c \u0432\u0430\u043b\u044e\u0442\u0443 \xab\u043d\u0430 \u0432\u0441\u044f\u043a\u0438\u0439 \u0441\u043b\u0443\u0447\u0430\u0439 \u043f\u0435\u0440\u0435\u0434 \u0441\u0430\u043c\u043c\u0438\u0442\u043e\u043c\xbb \u0437\u043d\u0430\u0447\u0438\u0442 \u043f\u043b\u0430\u0442\u0438\u0442\u044c \u0431\u0430\u043d\u043a\u0443 \u0441\u043f\u0440\u0435\u0434 \u0437\u0430 \u0441\u043e\u0431\u044b\u0442\u0438\u0435, \u043a\u043e\u0442\u043e\u0440\u043e\u0433\u043e \u0435\u0449\u0451 \u043d\u0435 \u0431\u044b\u043b\u043e. \u0421\u0447\u0438\u0442\u0430\u0442\u044c, \u0447\u0442\u043e \u0442\u043e\u0440\u0433\u043e\u0432\u044b\u0435 \u0432\u043e\u0439\u043d\u044b \u0431\u043e\u043b\u044c\u0448\u0438\u0445 \u0441\u0442\u0440\u0430\u043d \u0420\u043e\u0441\u0441\u0438\u0438 \u043d\u0435 \u043a\u0430\u0441\u0430\u044e\u0442\u0441\u044f, \u0442\u043e\u0436\u0435 \u043d\u0435 \u0432\u044b\u0439\u0434\u0435\u0442: \u0447\u0435\u0440\u0435\u0437 \u0446\u0435\u043d\u0443 \u043d\u0435\u0444\u0442\u0438 \u043e\u043d\u0438 \u0434\u043e\u0435\u0437\u0436\u0430\u044e\u0442 \u0434\u043e \u0431\u044e\u0434\u0436\u0435\u0442\u0430 \u0438 \u043a\u0443\u0440\u0441\u0430, \u043f\u0440\u043e\u0441\u0442\u043e \u0441 \u0437\u0430\u0434\u0435\u0440\u0436\u043a\u043e\u0439 \u0432 \u043c\u0435\u0441\u044f\u0446\u044b."}],"sources":[{"label":"https://www.interfax.ru/world/1117310","url":"https://www.interfax.ru/world/1117310"},{"label":"https://finance.yahoo.com/economy/policy/articles/trump-xi-showdown-casts-shadow-200000957.html","url":"https://finance.yahoo.com/economy/policy/articles/trump-xi-showdown-casts-shadow-200000957.html"},{"label":"https://www.bloomberg.com/news/videos/2026-09-21/trump-xi-to-meet-amidst-friction-on-wars-tech-trade-video","url":"https://www.bloomberg.com/news/videos/2026-09-21/trump-xi-to-meet-amidst-friction-on-wars-tech-trade-video"},{"label":"https://www.reuters.com/business/finance/us-treasurys-bessent-chinas-he-launch-talks-on-ai-trade-critical-minerals-2026-09-20","url":"https://www.reuters.com/business/finance/us-treasurys-bessent-chinas-he-launch-talks-on-ai-trade-critical-minerals-2026-09-20"},{"label":"https://www.bloomberg.com/news/articles/2026-09-20/us-stock-futures-up-ahead-of-talks-dollar-steady-markets-wrap","url":"https://www.bloomberg.com/news/articles/2026-09-20/us-stock-futures-up-ahead-of-talks-dollar-steady-markets-wrap"}],"sourceBodySha256":"c1bc79749a4e70a8e26a07aaaf0de06d665d61f9e8ea4735408da5f270991985"}')}}]);